def _ensure_exceptable(errors):
    """Ensures that errors are passable to except clause.
       I.e. should be BaseException subclass or a tuple."""
    is_exception = isinstance(errors, type) and issubclass(errors, BaseException)
    return errors if is_exception else tuple(errors)


class reraise:
    """Context manager and decorator for reraising exceptions.

    As a context manager:
        with reraise(ValueError, TypeError):
            ...  # ValueError becomes TypeError

    As a decorator:
        @reraise(ValueError, TypeError)
        def func():
            ...  # ValueError becomes TypeError

    If 'into' is callable, it's called with the caught exception:
        @reraise(ValueError, lambda e: MyError(str(e)))
        def func():
            ...
    """
    def __init__(self, errors, into):
        self.errors = _ensure_exceptable(errors)
        self.into = into

    def __enter__(self):
        return self

    def __exit__(self, exctype, excinst, exctb):
        if exctype is not None and issubclass(exctype, self.errors):
            if callable(self.into):
                raise self.into(excinst)
            else:
                raise_from(self.into, excinst)
            return True
        return False

    def __call__(self, func):
        errors = self.errors
        into = self.into

        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except errors as e:
                if callable(into):
                    raise into(e)
                else:
                    raise_from(into, e)
        return wrapper


class ErrorRateExceeded(Exception):

